mapper.insert:
MERGE INTO TB_EMP_STAT S USING (
SELECT #{empStat.code} AS EMP_STAT_CD, #{empStat.name} AS EMP_STAT_NM, #{empStat.description} AS EMP_STAT_EXPLN FROM DUAL
) SRC ON (S.EMP_STAT_CD = SRC.EMP_STAT_CD) WHEN NOT MATCHED THEN INSERT ( EMP_STAT_CD, EMP_STAT_NM, EMP_STAT_EXPLN ) VALUES ( SRC.EMP_STAT_CD, SRC.EMP_STAT_NM, SRC.EMP_STAT_EXPLN )
